import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.DC2M1AAK.js";const c=JSON.parse('{"title":"The playground","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/playground.md","filePath":"get-started/playground.md"}'),o={name:"get-started/playground.md"};function i(n,e,h,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="the-playground" tabindex="-1">The playground <a class="header-anchor" href="#the-playground" aria-label="Permalink to &quot;The playground&quot;">​</a></h1><p>The gateway&#39;s home page is a playground around the embeddable widget: the conversation in the centre, your past chats on the left, the live draft on the right. It is exactly what a host application gets from one <code>&lt;script&gt;</code> tag.</p><p>A hosted copy runs at <strong><a href="https://marg-playground.onrender.com" target="_blank" rel="noreferrer">https://marg-playground.onrender.com</a></strong> on the mock model with writes off. It sleeps when idle, so the first load takes a moment, and keeps no disk, so a session may be lost on a redeploy. Everything else is the real thing.</p><h2 id="what-to-try" tabindex="-1">What to try <a class="header-anchor" href="#what-to-try" aria-label="Permalink to &quot;What to try&quot;">​</a></h2><ul><li><strong>The opener.</strong> &quot;ticket for Northwind: login fails on mobile&quot; — one sentence that names the customer and the problem. The agent resolves the customer, asks the category, draws the Details card.</li><li><strong>Words beside an open ask.</strong> While the Details card is open, type &quot;what counts as production?&quot;. The model answers in a line; the card is drawn again under it. A typed &quot;yes&quot; while a card is open is never an answer to it.</li><li><strong>A premature yes.</strong> Type &quot;yes, create it&quot; before the summary. The runtime guard refuses: the summary must have been shown for this draft, and the reply must be a plain go-ahead by its whole content.</li><li><strong>Change something.</strong> On the summary, pick a section; the step&#39;s own card re-opens pre-filled; the summary returns.</li><li><strong>Reload.</strong> Refresh the page mid-journey. The open ask is drawn again from the transcript.</li></ul><h2 id="embedding-the-widget" tabindex="-1">Embedding the widget <a class="header-anchor" href="#embedding-the-widget" aria-label="Permalink to &quot;Embedding the widget&quot;">​</a></h2><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8787/widget.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-agent-auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Shadow DOM, zero dependencies, streaming replies, chips, forms, cards, tables, media, resume, nudges, voice notes. Or speak the <a href="/marg/components/client-protocol">client protocol</a> from your own app.</p>',8)])])}const u=t(o,[["render",i]]);export{c as __pageData,u as default};
